component pss_top {
    action A { }
}

component pss_top {
    action A {
        rand int a, b;
        constraint c {
            a + 1 < 4 * (b - 2);
            (a > 0) ? b == 1 : b == 2;
            -a != ~b;
            a in [1..4, 8];
        }
    }
}

package p {
    const int     i = -42;
    const int     h = 0xff;
    const bit[8]  b = 8'b1010_0101;
    const float64 f = 1.0e-9;
    const float32 g = 1.5;
    const bool    t = true;
    const string  s = "a \" b";
}
component pss_top {
    action A { }
}

component pss_top {
    function int f(int a, int b) {
        int t = a;
        if (a > b) { t = b; } else { t = a + 1; }
        repeat (3) { t = t + 1; }
        return t;
    }
    action A {
        rand int x;
        exec post_solve { x = 1; }
    }
}

component pss_top {
    action A { }
    action B { }
    action Top {
        A a1, a2;
        B b1;
        activity {
            parallel { a1; b1; }
            select { a2; b1; }
            repeat (2) { a1; }
        }
    }
}

component pss_top {
    action A {
        rand bit[4] x;
        rand bit[4] y;
        covergroup {
            cp_x : coverpoint x { bins lo = [0..3]; bins hi = [4..15]; }
            cp_y : coverpoint y;
            cr   : cross cp_x, cp_y;
        } cg;
    }
}

package p {
    const int W = 8;
}

import p::*;
component pss_top {
    action A { rand bit[p::W] f; }
}

component pss_top {
    action A { no_such_type_t f; }
}

// Read a block back and compare it against the pattern it is supposed to hold.
//
// completes_when: every word has been read and compared.
// waits for:      nothing.
//
// HOW A FAILURE IS REPORTED, and why it is only a message. PSS has no runtime
// error() -- std_pkg offers print() and message() only -- so a native model
// cannot fail a test by itself. The choices are a message or an environment
// contract (`import target function void ...`) that the integrator must supply.
// This model takes the message, so that it stands up and runs against any
// target without an integration step; an environment that wants a hard failure
// should bind its own reporter and call it from here.
//
// The comparison STOPS at the first mismatch. A corrupted transfer usually
// corrupts everything after the first bad word too, and a thousand messages
// bury the one that says where it started.
import addr_reg_pkg::*;
import std_pkg::*;
import mem_pkg::*;

extend component mem_c {

    target function void check(
        addr_handle_t  base,
        bit[32]        nbytes,
        mem_pattern_e  pattern,
        bit[32]        seed) {
        int      nwords = nbytes / 4;
        bit[32]  expected;
        bit[32]  actual;

        repeat (i : nwords) {
            expected = pattern_word(pattern, seed, i);
            actual   = read32(make_handle_from_handle(base, i * 4));

            if (actual != expected) {
                message(NONE, "mem_c: data mismatch at word %d: expected %x, read %x",
                        i, expected, actual);
                return;
            }
        }
    }
}

// Verify that a block of memory holds what it claims to hold.
//
// The input is a buffer, so this cannot run until the action that produced the
// block has COMPLETED -- which is the whole reason a memory block is a buffer
// rather than a struct passed around by hand.
//
// A block may have several checkers: a buffer permits any number of consumers.
import mem_pkg::*;
import addr_reg_pkg::*;

extend component mem_c {

    action check_a {
        input mem_blk_s  blk;

        // The model's honesty constraint. Data that came off the SPI wire is
        // MEM_PATTERN_UNKNOWN (see dma_c/actions/spi2mem_a.pss), and there is
        // no slave model here to predict it, so a scenario that tries to check
        // received data has no solution rather than a check that passes by
        // accident.
        constraint checkable_c {
            blk.pattern != MEM_PATTERN_UNKNOWN;
        }

        exec body {
            comp.check(make_handle_from_claim(blk.mem),
                       (bit[32])blk.mem.size,
                       blk.pattern,
                       blk.seed);
        }
    }
}

// A memory-to-memory copy running at the same time as a DMA-serviced SPI
// transmit.
//
// THE SCENARIO THE RESOURCE MODEL EXISTS TO MAKE POSSIBLE. Nothing here asserts
// that the two transfers may overlap; the model already implies it, and this
// scenario is what makes the implication observable:
//
//   * the copy claims a general-purpose channel and the SPI transmit claims the
//     one wired to the controller, so the two `lock`s never contend;
//   * the SPI shift engine is claimed by one of them only, so it is not a
//     bottleneck either;
//   * the memory blocks are distinct claims, so the allocator is required to
//     keep them apart -- two claims that may overlap in time shall resolve to
//     mutually exclusive addresses (§21.11.6).
//
// Change any one of those decisions and this scenario stops solving, which is
// what makes it worth having as a scenario rather than as a paragraph.
//
// THE THREE-BRANCH `parallel` is not an accident of formatting. The two halves
// of the SPI transfer must begin together (their stream requires it), and the
// copy must begin with them for the overlap to be real; nesting the SPI halves
// inside one branch as a sequence would break the stream.
extend component pss_top {

    action concurrent_dma_a {
        mem_c::fill_a        fill_copy;
        mem_c::fill_a        fill_spi;
        spi_c::configure_a   cfg;

        dma_c::mem2mem_a     copy;
        mem_c::check_a       chk;

        dma_c::mem2spi_a     dma_half;
        spi_c::dma_write_a   spi_half;

        activity {
            bind fill_copy.blk  copy.src;
            bind copy.dst       chk.blk;
            bind fill_spi.blk   dma_half.src;
            bind dma_half.data  spi_half.data;

            // The setup all has to happen; the order among the three is the
            // solver's business, because there is no dependency between them.
            schedule {
                fill_copy;
                fill_spi;
                cfg;
            }

            parallel {
                { copy; chk; }
                dma_half;
                spi_half;
            }
        }
    }
}

// Put the controller into a configuration: clock, framing, slave select, and
// who services the FIFOs.
//
// completes_when: SPI_DIV and the persistent fields of SPI_CTRL hold cfg, and
//                 the controller is enabled. No transfer has been started.
// waits for:      nothing. Straight-line stores.
//
// The CTRL register is written WHOLE rather than field-wise. Nothing is running
// at this point -- the caller holds the shift engine and has not pulsed start --
// so there is no state in the register worth preserving, and one bus write is
// both cheaper and easier to read than four read-modify-writes.
//
// `dir` and `start` are deliberately left at their reset values here: they
// belong to a transfer, not to a configuration, and start_transfer() sets them.
import spi_regs_pkg::*;
import spi_types_pkg::*;

extend component spi_c {

    target function void configure(spi_cfg_s cfg) {
        spi_ctrl_s  ctrl;
        spi_div_s   div;

        div.clk_div = cfg.clk_div;
        regs.div.write(div);

        ctrl.en        = 1;
        ctrl.start     = 0;
        ctrl.mode      = cfg.mode;
        ctrl.lsb_first = cfg.lsb_first;
        ctrl.cs        = cfg.cs;
        ctrl.dir       = SPI_XFER_WRITE;
        ctrl.dma_en    = (bit)cfg.dma_en;
        regs.ctrl.write(ctrl);
    }
}

// Put the controller into a configuration, and record that it is in it.
//
// THE OUTPUT IS THE POINT. Writing the state object is what makes every
// transfer action's `input spi_state_s` resolvable, so a scenario that traverses
// a transfer without ever configuring the controller has no legal schedule --
// and a scenario that switches between programmed and DMA styles is obliged to
// re-configure in between, because the two constrain `cfg.dma_en` differently.
//
// A state pool holds one object at a time and a writer never overlaps a reader,
// so this also cannot land in the middle of a transfer that is reading the
// configuration it is about to change.
import spi_types_pkg::*;

extend component spi_c {

    action configure_a {
        output spi_state_s  st;

        // Configuring is what makes the controller configured; nothing else
        // sets this bit.
        constraint configured_c {
            st.configured;
        }

        exec body {
            comp.configure(st.cfg);
        }
    }
}

// Program one channel's endpoints, length and mode. Does NOT start it.
//
// completes_when: CHn_SRC / CHn_DST / CHn_LEN and the RW fields of CHn_CSR
//                 describe `xfer`. The channel is not armed.
// waits for:      nothing. Straight-line stores.
//
// THE DERIVED FIELDS. `dir` decides three other bits, and this is the one place
// that knows how:
//
//   MEM_TO_MEM   both pointers increment; no handshake -- the engine moves the
//                whole block as fast as the bus lets it.
//   MEM_TO_PERI  the destination is a FIFO port: fixed pointer, and the
//                transfer advances only when the peripheral asks (hs_en). A
//                peripheral transfer with an incrementing destination would
//                walk across the peripheral's register map; one without the
//                handshake would overrun the FIFO.
//   PERI_TO_MEM  the mirror image.
//
// Deriving them here rather than taking them from the caller is why dma_xfer_s
// has four fields instead of seven: there is no legal combination the caller
// could have chosen that this does not produce.
//
// The CSR is written WHOLE. Nothing is running on the channel -- `en` is left
// clear and start_channel() sets it -- so there is no status to preserve and a
// read-modify-write would buy nothing.
import dma_regs_pkg::*;
import dma_types_pkg::*;

extend component dma_c {

    target function void configure_channel(int ch, dma_xfer_s xfer) {
        dma_ch_csr_s  csr;

        regs.ch_src[ch].write_val((bit[32])xfer.src);
        regs.ch_dst[ch].write_val((bit[32])xfer.dst);
        regs.ch_len[ch].write_val(xfer.nbytes);

        csr.en  = 0;
        csr.dir = xfer.dir;

        match (xfer.dir) {
            [DMA_MEM_TO_MEM]: {
                csr.src_mode = DMA_ADDR_INCR;
                csr.dst_mode = DMA_ADDR_INCR;
                csr.hs_en    = 0;
            }
            [DMA_MEM_TO_PERI]: {
                csr.src_mode = DMA_ADDR_INCR;
                csr.dst_mode = DMA_ADDR_FIXED;
                csr.hs_en    = 1;
            }
            [DMA_PERI_TO_MEM]: {
                csr.src_mode = DMA_ADDR_FIXED;
                csr.dst_mode = DMA_ADDR_INCR;
                csr.hs_en    = 1;
            }

            // dma_dir_e has exactly three values and all three are handled, so
            // this arm is unreachable -- but a match with no matching arm is a
            // runtime error nothing checks statically (§20.7.9), and the safe
            // fallback is the one that cannot walk a pointer across a
            // peripheral's registers.
            default: {
                csr.src_mode = DMA_ADDR_FIXED;
                csr.dst_mode = DMA_ADDR_FIXED;
                csr.hs_en    = 0;
            }
        }

        regs.ch_csr[ch].write(csr);
    }
}

// The DMA engine.
//
// It moves data between two endpoints without the processor in the loop. Which
// two endpoints a channel may connect is not a run-time choice: a peripheral
// request line is a wire, so the channels wired to the SPI controller are the
// only ones that can service it, and the rest can only move memory to memory
// (dma_types_pkg).
//
// The skeleton only (coding guidelines rule 3): members, the channel pool, and
// the solve-time constructor. Operations are in dma_c/functions/, their
// scenario wrappers in dma_c/actions/.
import addr_reg_pkg::*;
import dma_regs_pkg::*;
import dma_types_pkg::*;

component dma_c {

    // The MMIO bank: one engine-global register plus four per channel.
    dma_regs_c        regs;

    // The channels.
    //
    // PER ENGINE, because that is where channels are. Declaring the pool here
    // rather than in pss_top is what makes two dma_c instances independent --
    // and what makes the eight channels of THIS engine the eight things that
    // contend. The size is the real count (dma_types_pkg::DMA_NUM_CH), which is
    // what a `lock` needs to be meaningful.
    pool [dma_types_pkg::DMA_NUM_CH] dma_chan_s  chan_p;
    bind chan_p *;

    // Where the peripheral FIFO ports are, in absolute system addresses.
    //
    // A DMA channel servicing a peripheral is programmed with the address of
    // that peripheral's data register as its fixed endpoint, so the engine has
    // to know where the SPI controller landed in the address map. That is
    // SYSTEM INTEGRATION knowledge, not device knowledge -- the engine has no
    // way to derive it -- so it arrives through initialize(), from the component
    // that owns both devices (pss_top).
    //
    // Component attributes are writable during elaboration and read-only
    // afterwards (§9.1.6), which is exactly the lifetime this wants.
    bit[64]           spi_tx_addr;
    bit[64]           spi_rx_addr;

    // Bind the register bank and record the peripheral wiring. Called from the
    // environment's init_down exec: set_handle() is legal only from an init
    // exec, and so is writing the attributes above.
    solve function void initialize(
        addr_handle_t  base,
        bit[64]        tx_addr,
        bit[64]        rx_addr) {
        regs.set_handle(base);
        spi_tx_addr = tx_addr;
        spi_rx_addr = rx_addr;
    }

    // WHERE THE ENGINE GETS ENABLED, and why it is not here. A disabled engine
    // ignores every channel it arms, so DMA_CSR.en has to be set before the first
    // transfer -- once, ideally, with no scenario obliged to remember it.
    //
    // A component-scope `exec run_start` would be exactly that, and PSS does not
    // have one: run_start is legal on actions, flow and resource objects, and
    // structs, not on components (§20.1.2). So the engine enable lives in
    // dma_c/functions/enable.pss and every transfer calls it. It is idempotent and
    // it is one register write, which is a small price for an engine that cannot be
    // left off by an activity that forgot a setup step.
    //
    // (This model's tool accepts a component `exec run_start` without complaint --
    // a tier-2 gap, see README.md. It is not used.)
}

// The controller's half of a SPI-to-memory transfer serviced by the DMA.
//
// It produces the stream that dma_c::spi2mem_a consumes: this side clocks the
// slave's data into the receive FIFO, the DMA side drains it into memory, and
// the two run together for the same reason as the transmit pair above.
import spi_types_pkg::*;

extend component spi_c {

    action dma_read_a {
        output spi_data_s     data;
        input  spi_state_s    st;
        lock   spi_engine_s   eng;

        constraint style_c {
            st.configured;
            st.cfg.dma_en;
        }

        exec body {
            comp.dma_transfer(SPI_XFER_READ, data.nbytes);
        }
    }
}

// The DMA engine's MMIO register file: an engine-global control register and
// one bank of four registers per channel.
//
// ONE FILE, because a register bank is one artifact with one address decode
// (coding guidelines rule 5.2): the registers are meaningless apart from the
// group that maps them, the value structs are meaningless apart from their
// registers, and nobody includes one of the three without the others. The
// address-map constants sit here too -- they describe where this file's
// registers are, relative to the engine's base.
//
// All value structs are packed LITTLE_ENDIAN, so the first-declared field is at
// bit 0 and declaration order IS the bit numbering.
package dma_regs_pkg {
    import std_pkg::*;
    import addr_reg_pkg::*;
    import dma_types_pkg::*;

    // ---------------------------------------------------------------------
    // Address map
    // ---------------------------------------------------------------------

    static const bit[64]  DMA_CH_BASE   = 0x40;      // channel 0's bank
    static const bit[64]  DMA_CH_STRIDE = 0x20;      // bytes between banks
    static const bit[64]  DMA_REG_SPAN  =
        DMA_CH_BASE + DMA_NUM_CH * DMA_CH_STRIDE;

    // ---------------------------------------------------------------------
    // A plain 32-bit register with no field structure
    // ---------------------------------------------------------------------
    //
    // The address and length registers. With a bit-vector value type,
    // read()/read_val() and write()/write_val() are equivalent (§21.14.1).
    pure component dma_word_r : reg_c<bit[32], READWRITE, 32> {}

    // ---------------------------------------------------------------------
    // DMA_CSR -- engine-global control (offset 0x00)
    // ---------------------------------------------------------------------
    struct dma_csr_s : packed_s<> {
        rand bit      en;            //  0     RW  engine enable
        rand bit      pause;         //  1     RW  hold off all channel arbitration
        rand bit[30]  reserved;      // 31:2   RO
    }

    pure component dma_csr_r : reg_c<dma_csr_s, READWRITE, 32> {}

    // ---------------------------------------------------------------------
    // CHn_CSR -- per-channel control / status (bank offset 0x00)
    // ---------------------------------------------------------------------
    //
    // WHY THE STATUS BITS ARE PLAIN RO AND NOT CLEAR-ON-READ. A device whose
    // status read consumes the status forces every operation to read it exactly
    // once and carry the value, and makes a second reader steal the first one's
    // completion. This device clears `done` and `err` when the channel is
    // re-enabled instead, which is what makes wait_done()'s polling loop
    // (dma_c/functions/wait_done.pss) safe to write as a loop at all.
    //
    // `busy` means the arbiter is currently servicing this channel -- not that
    // the channel is armed. It is not a completion indicator.
    struct dma_ch_csr_s : packed_s<> {
        rand bit               en;         //  0     RW  arm / start; cleared by hardware on done
        rand dma_dir_e         dir;        //  2:1   RW  which endpoints
        rand dma_addr_mode_e   src_mode;   //  3     RW  source pointer: fixed or incrementing
        rand dma_addr_mode_e   dst_mode;   //  4     RW  destination pointer
        rand bit               hs_en;      //  5     RW  advance on the peripheral request line
        rand bit               busy;       //  6     RO  currently being serviced
        rand bit               done;       //  7     RO  transfer complete
        rand bit               err;        //  8     RO  bus error during transfer
        rand bit[23]           reserved;   // 31:9   RO
    }

    pure component dma_ch_csr_r : reg_c<dma_ch_csr_s, READWRITE, 32> {}

    // ---------------------------------------------------------------------
    // The bank
    // ---------------------------------------------------------------------
    //
    // ONE group for the whole engine, with the per-channel registers as arrays,
    // rather than one group per channel bound to its own region. The engine's
    // operations take a channel number (a claimed dma_chan_s instance_id), so
    // indexed access -- `regs.ch_csr[ch]` -- is what the caller already has;
    // per-channel groups would buy index-free access at the cost of turning
    // every operation into a component-array lookup on a solved value.
    pure component dma_regs_c : reg_group_c {
        dma_csr_r      csr;                       // 0x00  engine control

        dma_ch_csr_r   ch_csr[dma_types_pkg::DMA_NUM_CH];        // bank + 0x00
        dma_word_r     ch_src[dma_types_pkg::DMA_NUM_CH];        // bank + 0x04  source address
        dma_word_r     ch_dst[dma_types_pkg::DMA_NUM_CH];        // bank + 0x08  destination address
        dma_word_r     ch_len[dma_types_pkg::DMA_NUM_CH];        // bank + 0x0c  length in bytes

        function bit[64] get_offset_of_instance(string name) {
            match (name) {
                ["csr"]: return 0x00;
                default: return -1;
            }
        }

        function bit[64] get_offset_of_instance_array(string name, int index) {
            match (name) {
                ["ch_csr"]: return DMA_CH_BASE + index * DMA_CH_STRIDE + 0x00;
                ["ch_src"]: return DMA_CH_BASE + index * DMA_CH_STRIDE + 0x04;
                ["ch_dst"]: return DMA_CH_BASE + index * DMA_CH_STRIDE + 0x08;
                ["ch_len"]: return DMA_CH_BASE + index * DMA_CH_STRIDE + 0x0c;
                default:    return -1;
            }
        }
    }
}

// A DMA-SERVICED transfer, from the controller's side: arm it, then wait.
//
// completes_when: nbytes bytes have been shifted and SPI_STATUS.done is set.
// waits for:      the DMA channel wired to this controller to move every word.
//
// THE BODY IS SHORT BECAUSE THE OTHER HALF IS SOMEBODY ELSE'S. The processor's
// entire job in a DMA-serviced transfer is to arm both ends and wait; the words
// move between the FIFO and memory without it. That asymmetry -- almost no code
// on this side, a whole channel programming sequence on the other -- is the
// thing this model is trying to show, so it gets its own named operation rather
// than being inlined into the two actions that call it.
//
// It requires SPI_CTRL.dma_en to have been configured (spi_c/actions/ constrains
// it). Without it the controller never raises its request line, the DMA channel
// never sees a request, and this waits forever -- a hang, not an error, which is
// exactly why the requirement is a constraint the solver enforces rather than a
// check this function could make.
import spi_types_pkg::*;

extend component spi_c {

    target function void dma_transfer(spi_dir_e dir, bit[32] nbytes) {
        start_transfer(dir, nbytes);
        wait_done();
    }
}

// The DMA engine's shared data: what a channel is, what a transfer is, and
// which channels are wired to which peripheral request lines.
//
// Grouped into one file (coding guidelines rule 1): plain data and the resource
// object are reached by type name, never included on their own.
package dma_types_pkg {

    // ---------------------------------------------------------------------
    // Build-time configuration of the engine
    // ---------------------------------------------------------------------

    // How many channels the engine has. Sizes both the channel resource pool
    // (dma_c) and the per-channel register arrays (dma_regs_pkg), which is why
    // it lives here rather than in either of them.
    static const int  DMA_NUM_CH    = 8;

    // THE POINT OF THIS MODEL'S CHANNEL RULES.
    //
    // A peripheral request line is a wire, so a channel that services the SPI
    // transmit FIFO is not a channel chosen at run time -- it is the one channel
    // the SPI's TX request is connected to. Channels 0 .. DMA_SPI_TX_CH-1 have
    // no peripheral wired to them and can therefore only move memory to memory.
    //
    // Modelling this as constants plus a constraint on the claimed channel (see
    // the actions under dma_c/actions/) rather than as three separate channel
    // pools is deliberate: it keeps ONE pool, so the solver still sees that a
    // memory-to-memory copy and a SPI transfer contend for nothing, while an
    // over-subscribed SPI direction is a resource conflict rather than a silent
    // reuse of the wrong wire.
    static const int  DMA_SPI_TX_CH = 6;    // memory -> SPI transmit FIFO
    static const int  DMA_SPI_RX_CH = 7;    // SPI receive FIFO -> memory

    // ---------------------------------------------------------------------
    // Data types
    // ---------------------------------------------------------------------

    // What the channel's address pointers do as the transfer advances.
    //
    // A FIFO endpoint must NOT increment -- every word goes to the same data
    // register -- so this is not a free choice for a peripheral transfer. The
    // transfer functions derive it from the direction rather than taking it
    // from the caller; see dma_c/functions/configure_channel.pss.
    enum dma_addr_mode_e : bit[1] {
        DMA_ADDR_FIXED = 0,
        DMA_ADDR_INCR  = 1
    }

    // Which pair of endpoints a transfer connects. This is a register field
    // (CH_CSR.dir), so it has a base type and fixed encodings.
    enum dma_dir_e : bit[2] {
        DMA_MEM_TO_MEM  = 0,
        DMA_MEM_TO_PERI = 1,
        DMA_PERI_TO_MEM = 2
    }

    // One transfer's worth of channel programming.
    //
    // Plain data, not a flow object: it carries no scheduling meaning. It exists
    // so the configure / start / wait split (dma_c/functions/) has one argument
    // rather than five, and so a caller can describe a transfer without knowing
    // the register layout.
    //
    // WHAT IS NOT IN IT is deliberate. The pointer modes and the handshake
    // enable are not free choices -- they follow from `dir`, because a FIFO
    // endpoint is always fixed and always paced by its request line.
    // configure_channel() derives them, so a caller cannot get the combination
    // wrong.
    //
    // Addresses are bit[64] because that is what addr_value() returns; the
    // registers narrow them.
    struct dma_xfer_s {
        bit[64]           src;
        bit[64]           dst;
        bit[32]           nbytes;
        dma_dir_e         dir;
    }

    // A DMA channel.
    //
    // A RESOURCE, not a flow object: a transfer does not care what the previous
    // user of the channel put in it, only that nobody else is using it now
    // (choosing-constructs, "flow object vs resource"). Every transfer action
    // `lock`s one, so two transfers can never share a channel, while transfers
    // on different channels are free to overlap -- which is the whole reason a
    // multi-channel engine exists.
    //
    // No fields: instance_id is the channel number and is all a transfer needs.
    // The pool that gives it its count lives in dma_c, so each engine instance
    // has its own set of channels.
    resource dma_chan_s {
    }
}

// The controller's half of a memory-to-SPI transfer serviced by the DMA.
//
// It consumes the stream that dma_c::mem2spi_a produces. Because the coupling
// is a `stream`, this action and that one begin together and neither can appear
// in a scenario without the other -- a stream has exactly one producer and
// exactly one consumer (§9.3.2). No activity has to say "run these two in
// parallel"; a scenario that tries to schedule them any other way has no
// solution.
//
// Note what this action does NOT reference: no memory block, no DMA channel.
// The controller does not know where the data is coming from -- it raises a
// request line when its FIFO has room, and something answers. Modelling it as a
// stream endpoint rather than as an action that reads memory is what keeps that
// true.
import mem_pkg::*;
import spi_types_pkg::*;

extend component spi_c {

    action dma_write_a {
        input  spi_data_s     data;
        input  spi_state_s    st;
        lock   spi_engine_s   eng;

        constraint style_c {
            st.configured;
            st.cfg.dma_en;      // the controller must be raising DMA requests
        }

        exec body {
            comp.dma_transfer(SPI_XFER_WRITE, data.nbytes);
        }
    }
}

// Enable the engine.
//
// completes_when: DMA_CSR.en is set.
// waits for:      nothing.
//
// IDEMPOTENT, AND CALLED ON EVERY TRANSFER. The engine has no per-transfer
// state in this register -- `en` is a master enable and `pause` is not touched
// here -- so setting it again costs one bus write and removes a whole class of
// scenario bug: a test whose first transfer silently does nothing because no
// step in the activity enabled the engine.
//
// See dma_c.pss for why this is not a component `exec run_start`.
//
// write_field() rather than a whole-register write, because `pause` belongs to
// whoever set it and this operation has no opinion about it.
import dma_regs_pkg::*;

extend component dma_c {

    target function void enable() {
        regs.csr.write_field("en", 1);
    }
}

// Write `pattern` over a block of memory, one 32-bit word at a time.
//
// completes_when: every word of [base, base+nbytes) holds pattern_word() of its
//                 index.
// waits for:      nothing. Straight-line stores.
//
// `target`, because it is memory traffic: legal from exec body / run_start /
// run_end and from functions reached by them, and from nowhere else.
//
// Word at a time rather than write_bytes(): the block sizes here are word
// multiples by construction (mem_pkg::mem_blk_s.size_c), and a word store is
// what a processor doing this would actually issue.
import addr_reg_pkg::*;
import mem_pkg::*;

extend component mem_c {

    target function void fill(
        addr_handle_t  base,
        bit[32]        nbytes,
        mem_pattern_e  pattern,
        bit[32]        seed) {
        int nwords = nbytes / 4;

        repeat (i : nwords) {
            write32(make_handle_from_handle(base, i * 4),
                    pattern_word(pattern, seed, i));
        }
    }
}

// Produce a block of memory holding known data.
//
// This is where a mem_blk_s comes from, and therefore where every data flow in
// this model starts. The buffer is an OUTPUT, so nothing that consumes a block
// -- a DMA copy, a SPI transmit -- can be scheduled before this completes. That
// ordering is stated once, here, and no activity has to repeat it.
import mem_pkg::*;
import addr_reg_pkg::*;

extend component mem_c {

    action fill_a {
        output mem_blk_s  blk;

        // You cannot write a pattern that is defined as unpredictable.
        constraint pattern_c {
            blk.pattern != MEM_PATTERN_UNKNOWN;
        }

        exec body {
            comp.fill(make_handle_from_claim(blk.mem),
                      (bit[32])blk.mem.size,
                      blk.pattern,
                      blk.seed);
        }
    }
}

// Copy one block of memory to another.
//
// The SPI controller is not involved, and neither is any peripheral request
// line, so this is the one transfer kind that may use a general-purpose
// channel -- and, by the constraint below, may use ONLY one. The SPI channels
// are wired to the controller and are not available for general copying.
//
// WHY THE DESTINATION IS AN OUTPUT BUFFER. A copy produces a block that another
// action can consume -- check it, transmit it, copy it onward -- and the buffer
// is what makes that consumer wait until this transfer has COMPLETED. The
// content constraint is what makes the copy checkable: the destination holds
// what the source held, which is the entire claim a memory-to-memory DMA makes.
import addr_reg_pkg::*;
import mem_pkg::*;
import dma_types_pkg::*;

extend component dma_c {

    action mem2mem_a {
        input  mem_blk_s     src;
        output mem_blk_s     dst;
        lock   dma_chan_s    ch;

        // A general-purpose channel: no peripheral is wired to it.
        constraint channel_c {
            ch.instance_id < DMA_SPI_TX_CH;
        }

        // A copy is a copy: same length, same contents.
        constraint copy_c {
            dst.mem.size == src.mem.size;
            dst.pattern  == src.pattern;
            dst.seed     == src.seed;
        }

        exec body {
            dma_xfer_s  xfer;

            xfer.src    = addr_value(make_handle_from_claim(src.mem));
            xfer.dst    = addr_value(make_handle_from_claim(dst.mem));
            xfer.nbytes = (bit[32])src.mem.size;
            xfer.dir    = DMA_MEM_TO_MEM;

            comp.transfer((int)ch.instance_id, xfer);
        }
    }
}

// Feed a block of memory into the SPI controller's transmit FIFO.
//
// THE DMA HALF of a DMA-serviced SPI write. The other half is
// spi_c::dma_write_a, and the two are coupled by the spi_data_s stream: exactly
// one producer, exactly one consumer, both starting together (§9.3.2). Neither
// can be scheduled without the other, which is the correct statement about a
// transfer that neither side can complete alone.
//
// THE CHANNEL IS NOT A CHOICE. The SPI's transmit request is wired to one
// channel, so this action can only claim that one. Two consequences fall out of
// the resource model without further ado:
//
//   * two concurrent memory-to-SPI transfers are impossible -- there is one
//     wire and `lock` gives it to one action at a time;
//   * a memory-to-memory copy and this transfer never contend, because
//     mem2mem_a is constrained off this channel. They run in parallel, which is
//     what a multi-channel engine is for.
import addr_reg_pkg::*;
import mem_pkg::*;
import spi_types_pkg::*;
import dma_types_pkg::*;

extend component dma_c {

    action mem2spi_a {
        input  mem_blk_s     src;
        output spi_data_s    data;
        lock   dma_chan_s    ch;

        // The channel the SPI transmit request line is wired to.
        constraint channel_c {
            ch.instance_id == DMA_SPI_TX_CH;
        }

        // The stream carries the length the controller must be armed with, so
        // the two halves agree about how much data is in flight.
        constraint size_c {
            data.nbytes == src.mem.size;
        }

        exec body {
            dma_xfer_s  xfer;

            xfer.src    = addr_value(make_handle_from_claim(src.mem));
            xfer.dst    = comp.spi_tx_addr;    // the FIFO port: a fixed endpoint
            xfer.nbytes = (bit[32])src.mem.size;
            xfer.dir    = DMA_MEM_TO_PERI;

            comp.transfer((int)ch.instance_id, xfer);
        }
    }
}

// The processor's view of system memory: the agent that puts data into a block
// and the agent that checks a block's contents.
//
// It has no registers and no attributes, because memory is not a device here --
// it is storage the processor reaches with ordinary loads and stores. The
// component exists so that filling and checking are ACTIONS, schedulable
// alongside the transfers that move the data, rather than helper code somebody
// has to remember to call.
//
// The address space this component's actions allocate from is NOT declared
// here. A claim binds to the nearest matching space going up the component tree
// (§21.11.7), so system RAM belongs to the system -- see pss_top.
//
// The skeleton only (coding guidelines rule 3); the operations are in
// mem_c/functions/ and their scenario wrappers in mem_c/actions/.
component mem_c {
}

// Fill a block, copy it with the DMA, check the copy.
//
// The scenario the memory-to-memory path exists for, and the only one in this
// model that verifies data end to end: the copy constraint on mem2mem_a says
// the destination holds what the source held, and check_a is what makes that
// claim testable.
//
// WHY THE `bind` STATEMENTS. Three mem_blk_s objects are in flight and they all
// come from the same pool, so "check the block the copy produced" is not
// something the listing order says -- without the binds the solver is free to
// point the check at the block the fill produced, and the scenario would pass
// while testing nothing. The binds pin the identities; the buffers then supply
// the ordering.
extend component pss_top {

    action mem_copy_a {
        mem_c::fill_a     fill;
        dma_c::mem2mem_a  copy;
        mem_c::check_a    chk;

        activity {
            bind fill.blk copy.src;
            bind copy.dst chk.blk;

            fill;
            copy;
            chk;
        }
    }
}

// System memory: the buffer object every data movement in this model starts or
// ends with, and the plain data that describes it.
//
// One file, because these types are looked up by NAME from wherever they are
// used and are never included selectively (coding guidelines rule 1). There is
// no build that wants the fill pattern enum but not the block it describes.
package mem_pkg {
    import addr_reg_pkg::*;

    // What a memory block CONTAINS, described well enough that a consumer can
    // predict every word of it (mem_c/functions/pattern_word.pss).
    //
    // Carried in the buffer rather than passed between actions, because the
    // producer and the consumer of a block are usually in different components
    // -- and because a copy has to be able to say "the destination now holds
    // what the source held", which is a statement about the object, not about
    // either action.
    //
    // UNKNOWN is the one that earns its place. Data that arrived over the SPI
    // wire was produced by a device this model does not model, so it is not
    // predictable and shall not be checked. Making that a value of this enum,
    // and constraining check_a to reject it, turns "you cannot check received
    // data without a slave model" from a comment into an unschedulable
    // scenario.
    enum mem_pattern_e {
        MEM_PATTERN_ZERO,       // all words zero
        MEM_PATTERN_INCR,       // word i == seed + i
        MEM_PATTERN_PRAND,      // word i == a reproducible hash of seed and i
        MEM_PATTERN_UNKNOWN     // produced by the DUT; contents not predictable
    }

    // A block of system memory: THE unit of data this system moves.
    //
    // A `buffer` rather than a `stream` or a `struct`, deliberately:
    //
    //   * buffer   a consumer may not begin until the producer COMPLETES, which
    //              is exactly the semantics of "fill it, then DMA it, then check
    //              it". The ordering in every scenario below comes from this,
    //              not from the shape of an activity block.
    //   * not a stream, because a filled block persists and may have several
    //     consumers -- a stream permits exactly one.
    //   * not a struct, because it carries scheduling meaning.
    //
    // THE CLAIM IS THE ALLOCATION. Declaring a claim inside a flow object causes
    // allocation when the object is instantiated (§21.11), so each block gets
    // its own addresses and two blocks live simultaneously never overlap. That
    // is what makes a memory-to-memory copy a copy rather than a no-op, and it
    // is why the claim lives here rather than in each action that touches a
    // block: an action-local claim would give the producer and the consumer
    // different memory.
    //
    // The claim is TRANSPARENT so a scenario may constrain the address (see
    // pss_top: the system RAM region is added to a transparent space). Nothing
    // here does, but the alignment and size rules below need the size to be
    // solvable, and a transparent claim keeps the address available to a
    // scenario that wants to place a block deliberately.
    buffer mem_blk_s {
        rand transparent_addr_claim_s<>  mem;
        rand mem_pattern_e               pattern;
        rand bit[32]                     seed;

        // The transfer sizes this system supports. A DMA length register is
        // 32 bits, but nothing here needs to model a transfer bigger than a
        // few pages, and an unbounded size makes every scenario slow to solve.
        constraint size_c {
            mem.size in [4..4096];
            mem.size % 4 == 0;          // whole words: every engine here is 32-bit
        }

        // Word alignment is a DEVICE rule, not a preference: both the DMA
        // address registers and the SPI FIFO path move whole 32-bit words.
        constraint align_c {
            mem.alignment == 4;
        }
    }
}

// The data model shared by fill() and check(): word i of a block.
//
// ONE function, called by both, is the whole point -- a filler and a checker
// that each compute the expected data separately are two chances to be wrong
// about the same thing, and they drift.
//
// `pure`: no side effects, non-void, no output parameters, and the result
// depends only on the arguments. A tool is allowed to cache it, which is
// correct here (§20.2.1.4).
//
// Unqualified rather than `target`: nothing in it touches the device, so it is
// callable from a solve exec too if a scenario ever wants to predict a word at
// generation time.
import mem_pkg::*;

extend component mem_c {

    pure function bit[32] pattern_word(mem_pattern_e pattern, bit[32] seed, int idx) {
        match (pattern) {
            [MEM_PATTERN_ZERO]:  return 0;
            [MEM_PATTERN_INCR]:  return seed + idx;

            // A cheap reproducible scramble -- Knuth's multiplicative constant.
            // Reproducible is the requirement: check() has to be able to
            // recompute it, so urandom() would be exactly wrong here.
            [MEM_PATTERN_PRAND]: return (seed + idx) * 0x9e3779b9;

            // MEM_PATTERN_UNKNOWN. There is no expected value -- that is what
            // the pattern means -- and callers are constrained never to ask
            // (see mem_c/actions/check_a.pss). Returning zero rather than
            // leaving the match arm out keeps the runtime error a caller would
            // otherwise hit from being the FIRST report of the mistake; the
            // constraint is.
            default:             return 0;
        }
    }
}

// Receive into a block of memory, processor-driven.
//
// The block is an OUTPUT: this action is where received data enters the model,
// so anything that wants to look at it is scheduled after this completes.
import addr_reg_pkg::*;
import mem_pkg::*;
import spi_types_pkg::*;

extend component spi_c {

    action prog_read_a {
        output mem_blk_s      dst;
        input  spi_state_s    st;
        lock   spi_engine_s   eng;

        constraint style_c {
            st.configured;
            !st.cfg.dma_en;     // programmed: the processor moves the words
        }

        // What a slave sent us is not something this model can predict -- there
        // is no slave model here. Marking the block UNKNOWN makes that explicit
        // and makes a check_a on it unschedulable rather than wrong.
        constraint content_c {
            dst.pattern == MEM_PATTERN_UNKNOWN;
        }

        exec body {
            comp.program_read(make_handle_from_claim(dst.mem),
                              (bit[32])dst.mem.size);
        }
    }
}

// Transmit a block of memory, processor-driven.
//
// The DMA engine is not involved and is not mentioned: this action claims a
// memory block, the shift engine, and nothing else. That is what makes it the
// baseline the DMA-serviced path is worth comparing against.
import addr_reg_pkg::*;
import mem_pkg::*;
import spi_types_pkg::*;

extend component spi_c {

    action prog_write_a {
        input  mem_blk_s      src;
        input  spi_state_s    st;
        lock   spi_engine_s   eng;

        constraint style_c {
            st.configured;
            !st.cfg.dma_en;     // programmed: the processor moves the words
        }

        exec body {
            comp.program_write(make_handle_from_claim(src.mem),
                               (bit[32])src.mem.size);
        }
    }
}

// A PROGRAMMED receive: the processor takes every word out of the receive FIFO
// and stores it to memory itself.
//
// completes_when: nbytes bytes have been shifted in, stored to [dst, dst+nbytes)
//                 and SPI_STATUS.done is set.
// waits for:      each word to arrive, then the transfer to finish.
//
// On a READ the controller shifts out zeros to clock the slave's data in
// (spi_types_pkg::spi_dir_e), so there is no transmit data to supply and the
// loop is a mirror image of program_write().
//
// What lands in memory came from a device this model does not model, which is
// why the wrapping action marks the destination block MEM_PATTERN_UNKNOWN
// (spi_c/actions/prog_read_a.pss).
import addr_reg_pkg::*;
import spi_regs_pkg::*;
import spi_types_pkg::*;

extend component spi_c {

    target function void program_read(addr_handle_t dst, bit[32] nbytes) {
        int           nwords = nbytes / 4;
        spi_status_s  status;

        start_transfer(SPI_XFER_READ, nbytes);

        repeat (i : nwords) {
            repeat {
                yield;
                status = regs.status.read();
            } while (status.rx_valid == 0);

            write32(make_handle_from_handle(dst, i * 4), regs.rx.read_val());
        }

        wait_done();
    }
}

// A PROGRAMMED transmit: the processor moves every word from memory into the
// transmit FIFO itself.
//
// completes_when: nbytes bytes have been shifted out and SPI_STATUS.done is
//                 set.
// waits for:      the FIFO to accept each word, then the transfer to finish.
//
// This is the style the controller supports without any DMA involvement at all,
// and it is the reason the model tracks `dma_en` in a state object: with DMA
// request generation enabled, the DMA would be pulling words out of the FIFO at
// the same time as these stores are pushing them in. The action that wraps this
// constrains dma_en false (spi_c/actions/prog_write_a.pss); nothing about the
// register writes here would fail if it did not, which is precisely why the
// rule lives in a constraint rather than in a comment.
//
// The inner poll has a `yield` for the same reason wait_done() does: on a
// cooperatively scheduled target, a spin with no yield starves everything else.
import addr_reg_pkg::*;
import spi_regs_pkg::*;
import spi_types_pkg::*;

extend component spi_c {

    target function void program_write(addr_handle_t src, bit[32] nbytes) {
        int           nwords = nbytes / 4;
        spi_status_s  status;

        start_transfer(SPI_XFER_WRITE, nbytes);

        repeat (i : nwords) {
            repeat {
                yield;
                status = regs.status.read();
            } while (status.tx_empty == 0);

            regs.tx.write_val(read32(make_handle_from_handle(src, i * 4)));
        }

        wait_done();
    }
}

// The system: a processor's view of memory, a DMA engine, and a SPI controller
// wired to it.
//
// This file is the INTEGRATION, and it is the only file that knows any of the
// following: where the two devices sit in the address map, how big system RAM
// is, and which DMA channel endpoints correspond to which peripheral register.
// Everything under mem_c, dma_c and spi_c is device knowledge and would move to
// another SoC unchanged.
//
// The skeleton only (coding guidelines rule 3): members, pools, and the init
// exec that builds the address map. The scenarios are in pss_top/actions/.
import addr_reg_pkg::*;
import mem_pkg::*;
import dma_regs_pkg::*;
import spi_regs_pkg::*;
import spi_types_pkg::*;

component pss_top {

    // ---------------------------------------------------------------------
    // Address map
    // ---------------------------------------------------------------------

    static const bit[64]  SYS_RAM_BASE = 0x80000000;
    static const bit[64]  SYS_RAM_SIZE = 0x00100000;
    static const bit[64]  DMA_BASE     = 0x40000000;
    static const bit[64]  SPI_BASE     = 0x40010000;

    // ---------------------------------------------------------------------
    // Structure
    // ---------------------------------------------------------------------

    // ONE space for the whole system, transparent so that regions have known
    // addresses -- which is what lets a DMA channel be programmed with the
    // absolute address of the SPI FIFO port below.
    transparent_addr_space_c<>  sys_mem;

    mem_c   mem;
    dma_c   dma;
    spi_c   spi;

    // THE POOLS THAT CROSS DEVICE BOUNDARIES LIVE HERE, and that placement is
    // the reason the model composes at all:
    //
    //   mem_blk_s   is filled by mem_c, copied by dma_c, transmitted by spi_c.
    //               A pool inside any one of them would make the other two
    //               unable to see it, and every scenario below unschedulable.
    //   spi_data_s  couples a dma_c action to a spi_c action, so it can only
    //               live in an ancestor of both.
    //
    // Contrast the pools that did NOT come here: the DMA's channels (dma_c) and
    // the SPI's shift engine and configuration (spi_c). Those describe one
    // device's internals, and a second instance of that device should get its
    // own -- which is exactly what declaring them there gives.
    pool mem_blk_s   blk_p;
    bind blk_p *;

    pool spi_data_s  data_p;
    bind data_p *;

    // ---------------------------------------------------------------------
    // Elaboration
    // ---------------------------------------------------------------------
    //
    // Regions are added and register banks are bound here because that is the
    // only place either is legal: add_region() / add_nonallocatable_region() and
    // set_handle() are solve functions callable from init execs only.
    exec init_down {
        transparent_addr_region_s<>  ram;
        transparent_addr_region_s<>  dma_mmio;
        transparent_addr_region_s<>  spi_mmio;
        addr_handle_t                h;

        // System RAM: allocatable, and the only allocatable region, so every
        // mem_blk_s claim lands here.
        //
        // No `tag` is set on any region here, though the LRM gives every region
        // one (§21.10.3) and get_tag() would be the natural way for a check to
        // assert it is looking at RAM: the bundled addr_reg_pkg this model is
        // checked against declares addr_region_base_s without the field. See
        // README.md -- this is a library gap, not a modelling decision.
        ram.addr = SYS_RAM_BASE;
        ram.size = SYS_RAM_SIZE;
        (void)sys_mem.add_region(ram);

        // The device windows are NON-allocatable. Added with add_region() they
        // would be handed out as buffers, and the first memory fill would write
        // over a register bank -- a model that runs and corrupts the DUT.
        dma_mmio.addr = DMA_BASE;
        dma_mmio.size = DMA_REG_SPAN;
        h = sys_mem.add_nonallocatable_region(dma_mmio);

        // Wiring the two devices together. The DMA needs the absolute addresses
        // of the SPI FIFO ports, because a peripheral-serviced channel is
        // programmed with the data register as its fixed endpoint. The offsets
        // come from spi_regs_pkg -- the same constants the register group's
        // address decode uses -- so the two cannot disagree.
        dma.initialize(h,
                       SPI_BASE + SPI_TX_OFF,
                       SPI_BASE + SPI_RX_OFF);

        spi_mmio.addr = SPI_BASE;
        spi_mmio.size = SPI_REG_SPAN;
        h = sys_mem.add_nonallocatable_region(spi_mmio);
        spi.initialize(h);
    }
}

// Drain the SPI controller's receive FIFO into a block of memory.
//
// THE DMA HALF of a DMA-serviced SPI read; spi_c::dma_read_a is the other, and
// the spi_data_s stream couples them exactly as in mem2spi_a.
//
// A different channel from the transmit one, because a different request line
// is wired to it. That is what makes a simultaneous DMA transmit and DMA receive
// a question about the SPI shift engine (one, so no) rather than about DMA
// channels (two, so yes) -- see spi_c's engine pool.
import addr_reg_pkg::*;
import mem_pkg::*;
import spi_types_pkg::*;
import dma_types_pkg::*;

extend component dma_c {

    action spi2mem_a {
        input  spi_data_s    data;
        output mem_blk_s     dst;
        lock   dma_chan_s    ch;

        // The channel the SPI receive request line is wired to.
        constraint channel_c {
            ch.instance_id == DMA_SPI_RX_CH;
        }

        constraint size_c {
            dst.mem.size == data.nbytes;
        }

        // What arrives came from a slave this model does not model, so it is
        // not predictable. See mem_pkg::mem_pattern_e -- this is the constraint
        // that makes MEM_PATTERN_UNKNOWN worth having.
        constraint content_c {
            dst.pattern == MEM_PATTERN_UNKNOWN;
        }

        exec body {
            dma_xfer_s  xfer;

            xfer.src    = comp.spi_rx_addr;    // the FIFO port: a fixed endpoint
            xfer.dst    = addr_value(make_handle_from_claim(dst.mem));
            xfer.nbytes = data.nbytes;
            xfer.dir    = DMA_PERI_TO_MEM;

            comp.transfer((int)ch.instance_id, xfer);
        }
    }
}

// The SPI controller.
//
// It has one shift engine and one register bank, and it can be driven two ways:
// the processor moving every word through SPI_TX / SPI_RX, or the DMA moving
// them in response to the controller's FIFO request lines. Both styles are
// modelled, and the state object below is what keeps a scenario from mixing
// them up.
//
// The skeleton only (coding guidelines rule 3): members, pools, and the
// solve-time constructor. The operations are in spi_c/functions/ and their
// scenario wrappers in spi_c/actions/.
import addr_reg_pkg::*;
import spi_regs_pkg::*;
import spi_types_pkg::*;

component spi_c {

    // The MMIO bank. A top-level register group: bound once, from the
    // environment's init exec, by way of initialize() below.
    spi_regs_c        regs;

    // The controller's current configuration.
    //
    // PER CONTROLLER, which is what declaring the pool here rather than in
    // pss_top buys: two spi_c instances configured differently do not fight
    // over one state object. A state pool holds exactly one object at a time,
    // so this is "the mode the device is in", and every transfer action reads
    // it.
    pool spi_state_s  state_p;
    bind state_p *;

    // The shift engine: one, so at most one transfer at a time.
    //
    // Size 1 IS the exclusion. Every transfer action locks it, so a programmed
    // transfer and a DMA transfer on the same controller can never overlap --
    // and neither can two DMA transfers in opposite directions, even though
    // they use different DMA channels. That last one is the case a
    // channel-only model gets wrong.
    pool [1] spi_engine_s  eng_p;
    bind eng_p *;

    // Bind the bank to the region the system put this controller in. Called
    // from the environment's init_down exec: set_handle() is legal only from an
    // init exec, and component attributes are writable only during elaboration.
    solve function void initialize(addr_handle_t base) {
        regs.set_handle(base);
    }
}

// A DMA-serviced SPI receive: the controller clocks the slave's data in while
// the DMA drains the receive FIFO into memory.
//
// The mirror image of spi_dma_write_a, on the other peripheral channel
// (dma_types_pkg::DMA_SPI_RX_CH) -- and the reason the engine's SPI channels are
// two rather than one.
extend component pss_top {

    action spi_dma_read_a {
        spi_c::configure_a  cfg;
        spi_c::dma_read_a   spi_half;
        dma_c::spi2mem_a    dma_half;

        activity {
            bind spi_half.data dma_half.data;

            cfg;
            parallel {
                spi_half;
                dma_half;
            }
        }
    }
}

// A DMA-serviced SPI transmit: configure the controller for DMA, fill a block,
// and let the DMA feed the transmit FIFO while the controller shifts it out.
//
// THE `parallel` IS DOCUMENTATION, NOT MECHANISM. The two halves are coupled by
// a stream, which already requires them to begin together and forbids either
// from being scheduled alone; writing them in a parallel block only makes that
// visible to a reader. Replace it with a sequence and the scenario does not
// serialize -- it becomes unschedulable.
//
// The order in which the two halves program their devices is unspecified, and
// deliberately so: the FIFO request handshake is what synchronizes them. A
// controller armed before the channel simply asserts its request and waits.
extend component pss_top {

    action spi_dma_write_a {
        spi_c::configure_a   cfg;
        mem_c::fill_a        fill;
        dma_c::mem2spi_a     dma_half;
        spi_c::dma_write_a   spi_half;

        activity {
            bind fill.blk       dma_half.src;
            bind dma_half.data  spi_half.data;

            cfg;
            fill;
            parallel {
                dma_half;
                spi_half;
            }
        }
    }
}

// A processor-driven SPI receive: configure, then shift data in and store it.
//
// There is no check_a here, and there cannot be one: the received block is
// MEM_PATTERN_UNKNOWN, and check_a is constrained to refuse it. Adding a check
// would not produce a scenario that fails -- it would produce no scenario at
// all, which is the model saying "you need a slave model before you can verify
// received data".
extend component pss_top {

    action spi_prog_read_a {
        spi_c::configure_a  cfg;
        spi_c::prog_read_a  recv;

        activity {
            cfg;
            recv;
        }
    }
}

// A processor-driven SPI transmit: configure, fill a block, shift it out.
//
// The DMA engine appears nowhere in this scenario, and that is the point --
// this is the baseline the DMA-serviced transmit is worth comparing against.
//
// NOTHING HERE SAYS `dma_en == false`. prog_write_a does, and because the
// controller's configuration is a state object with one live value, that
// constraint propagates back into the configure action this scenario traverses:
// the solver is obliged to produce a configuration with DMA off. Compare
// spi_dma_write_a, which is the same shape and gets the opposite configuration
// for the same reason.
extend component pss_top {

    action spi_prog_write_a {
        spi_c::configure_a   cfg;
        mem_c::fill_a        fill;
        spi_c::prog_write_a  xmit;

        activity {
            bind fill.blk xmit.src;

            cfg;
            fill;
            xmit;
        }
    }
}

// The SPI controller's MMIO register file: one bank of six registers.
//
// One file for the bank, its register types and their value structs (coding
// guidelines rule 5.2). The package needs no directory because that is all
// there is (rule 2).
package spi_regs_pkg {
    import std_pkg::*;
    import addr_reg_pkg::*;
    import spi_types_pkg::*;

    // ---------------------------------------------------------------------
    // Address map
    // ---------------------------------------------------------------------

    static const bit[64]  SPI_CTRL_OFF   = 0x00;
    static const bit[64]  SPI_DIV_OFF    = 0x04;
    static const bit[64]  SPI_STATUS_OFF = 0x08;
    static const bit[64]  SPI_LEN_OFF    = 0x0c;
    static const bit[64]  SPI_TX_OFF     = 0x10;
    static const bit[64]  SPI_RX_OFF     = 0x14;
    static const bit[64]  SPI_REG_SPAN   = 0x20;

    // The FIFO port offsets are constants rather than literals inside the
    // offset function below because they have a SECOND reader: a DMA channel
    // servicing this controller is programmed with the absolute address of
    // SPI_TX or SPI_RX as its fixed endpoint (see pss_top, which wires the two
    // devices together). One declaration, so the group and the DMA cannot
    // disagree about where the FIFO is.

    // ---------------------------------------------------------------------
    // SPI_CTRL -- control (0x00)
    // ---------------------------------------------------------------------
    //
    // `start` is a write-only pulse: it arms a transfer of SPI_LEN bytes in the
    // direction `dir` and is read back as zero. Writing it with write_field()
    // is a read-modify-write of the register (§21.14.1), which is harmless here
    // -- nothing in this bank is clear-on-read.
    //
    // `dma_en` selects who services the FIFOs. Set, the controller raises its
    // request line and the DMA channel wired to it moves every word; clear, the
    // processor moves them through SPI_TX / SPI_RX itself. It is the one bit
    // that decides whether a transfer is programmed or DMA-based, which is why
    // the model tracks it in a state object (spi_types_pkg::spi_state_s) rather
    // than only in the device.
    struct spi_ctrl_s : packed_s<> {
        rand bit         en;          //  0     RW  controller enable
        rand bit         start;       //  1     WO  begin a transfer of SPI_LEN bytes
        rand spi_mode_e  mode;        //  3:2   RW  clock polarity / phase
        rand bit         lsb_first;   //  4     RW  bit order
        rand bit[2]      cs;          //  6:5   RW  which slave to select
        rand spi_dir_e   dir;         //  7     RW  transfer direction
        rand bit         dma_en;      //  8     RW  service the FIFOs by DMA request
        rand bit[23]     reserved;    // 31:9   RO
    }

    pure component spi_ctrl_r : reg_c<spi_ctrl_s, READWRITE, 32> {}

    // ---------------------------------------------------------------------
    // SPI_DIV -- clock divider (0x04)
    // ---------------------------------------------------------------------
    struct spi_div_s : packed_s<> {
        rand bit[8]      clk_div;     //  7:0   RW  SCLK = PCLK / (2 * (clk_div+1))
        rand bit[24]     reserved;    // 31:8   RO
    }

    pure component spi_div_r : reg_c<spi_div_s, READWRITE, 32> {}

    // ---------------------------------------------------------------------
    // SPI_STATUS -- status (0x08, read-only)
    // ---------------------------------------------------------------------
    //
    // Read-only and free of side effects, so it may be polled. `done` is
    // cleared by the next SPI_CTRL.start, not by reading it -- see the same
    // reasoning in dma_regs_pkg for the channel status bits.
    struct spi_status_s : packed_s<> {
        rand bit         busy;        //  0     RO  a transfer is in progress
        rand bit         tx_empty;    //  1     RO  SPI_TX will accept a word
        rand bit         rx_valid;    //  2     RO  SPI_RX holds a received word
        rand bit         done;        //  3     RO  SPI_LEN bytes have been transferred
        rand bit[28]     reserved;    // 31:4   RO
    }

    pure component spi_status_r : reg_c<spi_status_s, READONLY, 32> {}

    // ---------------------------------------------------------------------
    // SPI_LEN (0x0c), SPI_TX (0x10), SPI_RX (0x14)
    // ---------------------------------------------------------------------
    //
    // The FIFO ports are single-direction by construction: a read of SPI_TX or
    // a write of SPI_RX is an error the compiler catches, rather than a bus
    // access that quietly does the wrong thing.
    pure component spi_len_r : reg_c<bit[32], READWRITE, 32> {}
    pure component spi_tx_r  : reg_c<bit[32], WRITEONLY, 32> {}
    pure component spi_rx_r  : reg_c<bit[32], READONLY,  32> {}

    // ---------------------------------------------------------------------
    // The bank
    // ---------------------------------------------------------------------

    pure component spi_regs_c : reg_group_c {
        spi_ctrl_r    ctrl;      // 0x00
        spi_div_r     div;       // 0x04
        spi_status_r  status;    // 0x08  RO
        spi_len_r     len;       // 0x0c
        spi_tx_r      tx;        // 0x10  WO
        spi_rx_r      rx;        // 0x14  RO

        function bit[64] get_offset_of_instance(string name) {
            match (name) {
                ["ctrl"]:   return SPI_CTRL_OFF;
                ["div"]:    return SPI_DIV_OFF;
                ["status"]: return SPI_STATUS_OFF;
                ["len"]:    return SPI_LEN_OFF;
                ["tx"]:     return SPI_TX_OFF;
                ["rx"]:     return SPI_RX_OFF;
                default:    return -1;
            }
        }

        function bit[64] get_offset_of_instance_array(string name, int index) {
            return -1;
        }
    }
}

// The SPI controller's shared data: its configuration, the state object that
// says the controller is currently in that configuration, the stream that
// couples a DMA-serviced transfer's two halves, and the shift engine itself.
package spi_types_pkg {

    // The controller drives four chip selects, which is the width of the `cs`
    // field below and of SPI_CTRL.cs -- there is no separate count constant,
    // because a constant that only ever restates a field width is a second
    // place to be wrong.

    // Clock polarity / phase, in the usual numbering. A register field, so it
    // has a base type.
    enum spi_mode_e : bit[2] {
        SPI_MODE_0 = 0,
        SPI_MODE_1 = 1,
        SPI_MODE_2 = 2,
        SPI_MODE_3 = 3
    }

    // Which way the data of a transfer moves, from the CONTROLLER's point of
    // view: WRITE shifts memory data out to the slave, READ shifts slave data
    // in. A register field (SPI_CTRL.dir), so it has a base type.
    //
    // SPI is full duplex on the wire, and this field does not pretend
    // otherwise -- it selects which direction the controller sources and sinks
    // data for. On a READ the controller shifts out zeros, so a transfer needs
    // no transmit data to clock the slave's data in.
    enum spi_dir_e : bit[1] {
        SPI_XFER_WRITE = 0,
        SPI_XFER_READ  = 1
    }

    // Everything one `configure` writes into the controller.
    //
    // Plain data, so it can be a function argument -- a state object cannot be
    // (a flow-object instance field is only legal inside another flow object).
    // The state object below carries one of these; the operation takes it.
    struct spi_cfg_s {
        rand spi_mode_e  mode;
        rand bit[8]      clk_div;        // SCLK = PCLK / (2 * (clk_div+1))
        rand bit[2]      cs;             // which slave this configuration talks to
        rand bool        lsb_first;
        rand bool        dma_en;         // service the FIFOs by DMA request
    }

    // The configuration the controller IS in.
    //
    // A `state` object: a state pool holds exactly one at a time, a writer never
    // overlaps a reader, and every reader sees the last value written. That is
    // what makes "programmed transfers require dma_en == false, DMA transfers
    // require dma_en == true" schedule a re-configuration when a scenario mixes
    // the two styles -- instead of leaving it to the person writing the
    // activity to remember.
    //
    // `configured` is not a register bit; it is how the model says "reset does
    // not count as a configuration". Without it the initial object would be a
    // usable configuration and a transfer could be the first thing a scenario
    // does, which no real driver may assume.
    state spi_state_s {
        rand bool        configured;
        rand spi_cfg_s   cfg;

        // Out of reset: not configured, DMA off, slowest clock. `initial` is
        // true only for the object present before anything has written the
        // pool, so this constrains reset state and nothing else.
        constraint initial_c {
            initial -> (!configured && !cfg.dma_en && cfg.clk_div == 0);
        }
    }

    // The data of one DMA-serviced SPI transfer, in flight.
    //
    // A `stream`, and the kind choice is the model's claim about what a
    // DMA-serviced transfer IS: exactly one producer and one consumer, both
    // starting together (§9.3.2). A DMA channel feeding the SPI transmit FIFO
    // and the SPI transfer it feeds are not two things in sequence -- they are
    // one thing with two halves, and neither can make progress without the
    // other.
    //
    // Two consequences worth having:
    //
    //   * an unpaired half is UNSCHEDULABLE. dma_c::mem2spi_a cannot appear in
    //     a scenario without spi_c::dma_write_a, because a stream with no
    //     consumer cannot bind.
    //   * `parallel` in the scenarios below is documentation, not mechanism.
    //     The stream already requires the concurrent start.
    //
    // Had this been a buffer, the SPI half would have waited for the DMA half
    // to COMPLETE -- a deadlock dressed up as a model, since the DMA half only
    // completes when the FIFO drains.
    stream spi_data_s {
        rand bit[32]     nbytes;

        constraint size_c {
            nbytes in [4..4096];
            nbytes % 4 == 0;
        }
    }

    // The shift engine.
    //
    // One controller has one shifter, so a transfer of any style occupies the
    // whole controller for its duration. A pool of size 1 in spi_c plus a `lock`
    // on every transfer action is what says so, and it is what keeps a
    // programmed transfer from being scheduled alongside a DMA one.
    //
    // This is also why there is no chip-select resource: with one shifter there
    // is never a second transfer to conflict with, whatever slave it addresses.
    resource spi_engine_s {
    }
}

// Arm a configured channel.
//
// completes_when: CHn_CSR.en is set. The transfer is RUNNING, not finished.
// waits for:      nothing -- this is the arm half; wait_done() is the other.
//
// Setting `en` is also what clears the channel's `done` and `err` status
// (dma_regs_pkg), so a wait that follows this cannot observe the previous
// transfer's completion. That is the property the arm/wait split depends on,
// and it is why the model gives the device that behaviour rather than
// clear-on-read status.
//
// write_field() rather than a whole-register write: the configuration this is
// arming is already in the register and must survive. It is a read-modify-write
// on the bus (§21.14.1), which is safe here because nothing in this bank is
// clear-on-read.
import dma_regs_pkg::*;

extend component dma_c {

    target function void start_channel(int ch) {
        regs.ch_csr[ch].write_field("en", 1);
    }
}

// Arm a transfer of `nbytes` bytes in direction `dir` and pulse it into motion.
//
// completes_when: SPI_LEN and SPI_CTRL.dir are programmed and SPI_CTRL.start
//                 has been written. The transfer is RUNNING, not finished.
// waits for:      nothing -- this is the arm half. wait_done() is the other.
//
// Splitting arm from wait is what lets both transfer styles share this code.
// A programmed transfer has to interleave FIFO accesses between the two;
// a DMA transfer has nothing to do in between at all.
//
// TWO WRITES, IN THIS ORDER, and it matters. `dir` decides which way the shift
// engine sources data, so it has to be settled before the pulse; folding both
// into one write_fields() would coalesce them into a single bus
// read-modify-write and lose the ordering (§21.14.1). write_field() also names
// the field to the compiler, so a typo is a compile error rather than a wrong
// bit.
import spi_regs_pkg::*;
import spi_types_pkg::*;

extend component spi_c {

    target function void start_transfer(spi_dir_e dir, bit[32] nbytes) {
        regs.len.write_val(nbytes);
        regs.ctrl.write_field("dir", (bit[32])dir);
        regs.ctrl.write_field("start", 1);
    }
}

// A random mix of everything the system can do.
//
// The point of a `select` over the five directed scenarios, rather than a
// hand-written interleaving, is the transitions BETWEEN them: a DMA-serviced
// transfer following a programmed one requires the controller to be
// re-configured, and nothing in this file says so. The state object does
// (spi_types_pkg::spi_state_s), so every reconfiguration this scenario needs
// appears because the solver had to put it there.
//
// Each branch is a compound action of its own, so its internal ordering,
// binding and concurrency come with it.
extend component pss_top {

    action system_test_a {

        activity {
            repeat (4) {
                select {
                    do mem_copy_a;
                    do spi_prog_write_a;
                    do spi_prog_read_a;
                    do spi_dma_write_a;
                    do spi_dma_read_a;
                    do concurrent_dma_a;
                }
            }
        }
    }
}

// One complete transfer on one channel: configure, arm, wait, report.
//
// completes_when: the channel has reached DONE or ERR.
// waits for:      the transfer, and on a peripheral channel for the peripheral
//                 half of it.
//
// The end-to-end operation every action in dma_c/actions/ calls, and the only
// one they call. The core underneath it (enable / configure_channel /
// start_channel / wait_done) stays separate and public because a driver that
// arms several channels before waiting on any of them needs the pieces -- this
// wrapper adds no device knowledge, only the sequence.
//
// A failed transfer is reported once, here, rather than by each caller: PSS has
// no runtime error(), so a message is the strongest thing a native model can do
// (the same reasoning as mem_c/functions/check.pss).
import std_pkg::*;
import dma_types_pkg::*;

extend component dma_c {

    target function void transfer(int ch, dma_xfer_s xfer) {
        enable();
        configure_channel(ch, xfer);
        start_channel(ch);

        if (!wait_done(ch)) {
            message(NONE, "dma_c: channel %d reported a bus error", ch);
        }
    }
}

// Block until the armed transfer has moved all SPI_LEN bytes.
//
// completes_when: SPI_STATUS.done is set.
// waits for:      the transfer, however it is being serviced -- by this
//                 processor through the FIFO registers, or by a DMA channel.
//
// A POLLING LOOP WITH A yield. Without it, a target platform that schedules
// execs cooperatively would spin here forever and never let the concurrent
// half of a DMA transfer run -- and a DMA-serviced transfer is exactly the
// case where something else must run for this condition to ever become true.
//
// SPI_STATUS is READONLY and has no read side effects (spi_regs_pkg), which is
// what makes a re-read loop safe: `done` survives being observed and is cleared
// by the next start pulse.
import spi_regs_pkg::*;

extend component spi_c {

    target function void wait_done() {
        spi_status_s  status;

        repeat {
            yield;
            status = regs.status.read();
        } while (status.done == 0);
    }
}

// activity_shapes.pss
//
// Every activity composition statement, and what each one actually means.
//
// Demonstrates:
//   - sequential / parallel / schedule, and why they differ
//   - select with guards and weights; if-else; match
//   - repeat (count and while), foreach, replicate with a label array
//   - named sub-activities and hierarchical references
//   - join specifications
//   - atomic, to keep inference out of a block
//
// See: reference/lang/activity/01-activities.md
//      reference/lang/activity/03-scheduling-semantics.md

package shapes_pkg {
    enum op_mode_e { FAST, SLOW }
}

component engine_c {
    import shapes_pkg::*;

    action step {
        rand bit[8] id;
    }

    action fast_step { }
    action slow_step { }

    action shapes {
        rand op_mode_e     mode;
        rand bit[3] in [2..4] n;
        rand bool          use_dma;

        step s1, s2;
        step s_arr[4];

        array<bit[8],3> sizes = {1, 2, 3};

        activity {
            // Sequential: s2 begins after s1 completes.
            // (`sequence` is optional; a bare block means the same thing.)
            sequence {
                s1;
                s2;
            }

            // schedule: all of these happen, in any legal order.
            // This is the right default for "these must all occur".
            schedule {
                do step;
                do step;
                s_arr;                  // whole-array traversal: no inline
                                        // constraint or initializer allowed
            }

            // parallel: all branches BEGIN at the same time. Stronger than
            // schedule, and only correct when a common start is required.
            // A labelled block is a named sub-activity, so L.a and L.b can be
            // referenced from constraints below.
            L: parallel {
                a: do step;
                b: do step;
            }

            // A join specification changes what the statement AFTER the block
            // waits for. It is legal PSS (LRM 11.3.6) but is not accepted by
            // every front end, so it is shown here rather than compiled:
            //
            //     L2: parallel {
            //         p1: do step;
            //         p2: do step;
            //     } join_branch(p1)
            //
            // join_branch(labels) -- continue after those branches complete
            // join_select(n)      -- after n randomly selected branches
            // join_none           -- no scheduling dependency on the block
            // join_first(n)       -- a RUNTIME dependency only, on the first n

            // Choice made by the tool, with guards and weights.
            select {
                (mode == FAST) [3]: do fast_step;
                               [1]: do slow_step;
            }

            // Choice made by a solved value.
            if (use_dma) {
                do fast_step;
            } else {
                do slow_step;
            }

            match (n) {
                [2]:    do fast_step;
                [3..4]: do slow_step;
            }

            // Counted repetition. `repeat` gives no handles.
            repeat (4) {
                do step;
            }
            repeat (ri : 4) {
                do step with { id == ri; };
            }

            // Collection-driven repetition.
            // (an index variable may also be declared: `foreach (e : sizes [fi])`)
            foreach (e : sizes) {
                do step with { id == e; };
            }

            // replicate expands IN PLACE -- no extra scheduling layer -- and a
            // label array makes each expansion individually referenceable
            // (R[0], R[1], ...). A label inside replicate REQUIRES the array.
            // An index variable may also be declared -- `replicate (ni : n)` --
            // and referenced in the replicated statement.
            replicate (n) R[]: {
                do step;
            }

            // atomic keeps inferred actions from interleaving into this block.
            atomic {
                do fast_step;
                do slow_step;
            }
        }

        // Hierarchical references into the named sub-activity L.
        constraint parallel { L.a, L.b };
    }
}

component pss_top {
    engine_c eng;
}

// behavioral_coverage.pss
//
// requires: a front end implementing Clause 16 (cover / monitor)
//   Behavioral coverage is legal PSS 3.1 but is not implemented by every front
//   end. This file is excluded by name from the parse gate; the PSS below is
//   correct as written. Data coverage is in coverage.pss.
//
// Behavioral coverage: describing a scenario to OBSERVE.
//
// The one thing to internalize: a monitor RECOGNIZES a pattern in the executed
// scenario. It does not cause that pattern to be produced. If you need it
// produced, that is a constraint or an activity.
//
// Demonstrates:
//   - concat  : immediate consecutive matching
//   - sequence: consecutive matching with arbitrary gaps
//   - eventually / overlap / schedule / select
//   - action handles and constraints, which is what makes a pattern specific
//   - a covergroup sampled at the first match of a cover statement
//   - monitor traversal from another monitor
//
// See: reference/lang/coverage/02-behavioral-coverage.md

package bcov_pkg {
    enum lock_mode_e  { LOCKED, UNLOCKED }
    enum write_mode_e { WRITE_BACK, WRITE_THRU }
}

component dut_c {
    import bcov_pkg::*;

    action read  { rand bit[32] addr; rand lock_mode_e  lock_mode;  }
    action write { rand bit[32] addr; rand write_mode_e write_mode; }
    action reset { }
}

package mon_pkg {
    import bcov_pkg::*;

    // `concat` requires immediate consecutive matching: the read's checkpoint
    // IS the write's match point.
    monitor rd_immediately_after_wr {
        dut_c::write w;
        dut_c::read  r;

        activity {
            concat {
                w;
                r;
            }
        }

        // Without this the pattern matches almost any trace containing both.
        constraint w.addr == r.addr;
    }

    // `sequence` allows an arbitrary gap between the subscenarios.
    monitor rd_sometime_after_wr {
        dut_c::write w;
        dut_c::read  r;

        activity {
            sequence {
                w;
                r;
            }
        }

        constraint w.addr == r.addr;
    }

    // `eventually` matches its sub-scenario at any later checkpoint.
    monitor eventually_locked {
        dut_c::reset rst;
        dut_c::read  r;

        activity {
            sequence {
                rst;
                eventually r;
            }
        }

        constraint r.lock_mode == LOCKED;
    }

    // `schedule` -- any order, gaps and overlaps allowed, realizations
    // pairwise disjoint. `overlap` additionally requires a time instant at
    // which all members are simultaneously active.
    monitor two_writes_overlapping {
        dut_c::write w1;
        dut_c::write w2;

        activity {
            overlap {
                w1;
                w2;
            }
        }

        constraint w1.addr != w2.addr;
    }

    // `select` -- the realizations are the union of the alternatives'.
    monitor read_or_reset {
        activity {
            select {
                do dut_c::read;
                do dut_c::reset;
            }
        }
    }

    // Monitors compose: a monitor may be traversed from another monitor.
    monitor two_rd_after_wr {
        activity {
            schedule {
                do rd_immediately_after_wr;
                do rd_immediately_after_wr;
            }
        }
    }
}

component pss_top {
    import bcov_pkg::*;
    import mon_pkg::*;

    dut_c dut;

    // Instantiate an existing monitor type. Cover statements are only active
    // in component instances actually instantiated from the root component.
    c1 : cover rd_immediately_after_wr;
    c2 : cover two_rd_after_wr;

    // Or declare the scenario in place, with a covergroup sampled at the
    // FIRST MATCH of the cover statement's attempts. Where several first-match
    // realizations exist, the implementation may pick any of them.
    c3 : cover {
        dut_c::write w;
        dut_c::read  r;

        activity {
            w;
            r;
        }

        covergroup {
            cpw : coverpoint w.write_mode;
            cpr : coverpoint r.lock_mode;
            wXr : cross cpw, cpr;
        } cg;
    }
}

// constraints.pss
//
// Algebraic constraints, defaults, distributions, and procedural randomization.
//
// Demonstrates:
//   - hard constraints (rules) vs default value constraints (preferences)
//   - implication and if-else, and the fact that BOTH are bidirectional
//   - foreach and unique constraints
//   - dist, with := and :/ weights
//   - inline constraints on a traversal
//   - pre_solve / post_solve, and procedural randomize
//
// See: reference/lang/constraints/01-algebraic-constraints.md
//      reference/lang/constraints/03-randomization.md

package cst_pkg {
    enum xfer_mode_e { NARROW, WIDE }

    struct sub_s {
        rand bit[8] a;
        rand bit[8] b;
    }

    struct cfg_s {
        rand bit[16]      len;
        rand bit[32]      addr;
        rand xfer_mode_e  mode;
        rand bit[8]       chans[4];

        // rand propagates only through fields that are themselves rand.
        rand sub_s  solved;      // solved.a / solved.b ARE randomized
        sub_s       fixed;       // fixed.a / fixed.b are NOT

        constraint c_basic {
            len > 0 && len <= 4096;
            addr % 4 == 0;
        }

        // Implication is BIDIRECTIONAL: this also means
        // len < 512 -> mode != WIDE.
        constraint c_mode {
            mode == WIDE -> len >= 512;
        }

        // if-else in a constraint is likewise bidirectional.
        constraint c_align {
            if (len > 1024) {
                addr % 64 == 0;
            } else {
                addr % 4 == 0;
            }
        }

        // All four channel values differ.
        constraint c_unique {
            unique { chans };
        }

        // Iterative constraint over a collection.
        constraint c_each {
            foreach (chans[i]) {
                chans[i] < 8;
            }
        }

        // A preference, not a rule: overridable with `default disable len`
        // from a containing type.
        constraint c_pref {
            default len == 64;
        }

        // A soft constraint (3.1) is a preference that is discarded when it
        // conflicts with a hard constraint or a higher-priority soft one.
        // A dist directive shapes the value distribution and is itself the
        // LOWEST-priority soft constraint. Both are legal PSS (LRM 13.1.11,
        // 13.1.12) but are not accepted by every front end, so they are shown
        // here rather than compiled:
        //
        //     constraint { soft mode == NARROW; }
        //     constraint {
        //         dist addr in [0x0000_0000 := 1,               // each value
        //                       0x8000_0000..0x8FFF_FFFF :/ 8]; // across range
        //     }
    }
}

component dma_c {
    import cst_pkg::*;

    action xfer {
        rand cfg_s cfg;
        bit[32]    computed;      // derived, not solved

        exec pre_solve {
            // Set non-random inputs the solve will read. Writing a rand
            // scalar here would simply be overwritten by the solve.
            computed = 0;
        }

        exec post_solve {
            // Compute non-rand fields from solved values.
            computed = cfg.addr + cfg.len;

            // Procedural randomization: every target is solved together and
            // is treated as random whether or not it was declared rand.
            // Non-rand SUB-fields of a struct target are invariants.
            sub_s  v1;
            bit[4] v2;
            v1.b = 100;
            randomize v1, v2 with { v1.a < v2; };
        }
    }

    action test {
        xfer x1;
        xfer x2;

        activity {
            // Inline constraints apply to this traversal only.
            x1 with { cfg.mode == WIDE; };
            x2 with { cfg.len == 128; };
        }

        // Relate two traversals.
        constraint c_rel {
            x1.cfg.addr != x2.cfg.addr;
        }
    }
}

component pss_top {
    dma_c dma;
}

// coverage.pss
//
// Data coverage: covergroup.
//
// Behavioral coverage (cover / monitor) is in behavioral_coverage.pss.
//
// Demonstrates:
//   - an in-line covergroup, which may reference its enclosing scope
//   - a reusable covergroup type, which must be parameterized and must NOT
//   - explicit bins, bin arrays, ignore_bins and illegal_bins
//   - cross coverage
//   - coverage options
//
// See: reference/lang/coverage/01-data-coverage.md

package cov_pkg {
    enum xfer_mode_e  { NARROW, WIDE }
    enum lock_mode_e  { LOCKED, UNLOCKED }

    // A reusable covergroup type: it takes formal parameters and references
    // nothing from the scope in which it is declared.
    covergroup xfer_cg(bit[16] len, xfer_mode_e m) {
        // A bin per value, a bin per range, and a fixed number of bins
        // spanning a range. Without explicit bins a bit[16] coverpoint would
        // get auto bins (min(2**16, auto_bin_max) == 64 by default), which
        // reports 100% and means nothing.
        ln : coverpoint len {
            bins small[]  = [1..16];
            bins medium   = [17..1023];
            bins large[4] = [1024..4096];
            ignore_bins   unused = [0];
            illegal_bins  toobig = [4097..65535];
        }

        // An enum coverpoint: auto bins are exactly the enumeration, so they
        // are fine here.
        md : coverpoint m;

        // A cross references COVERPOINTS, never expressions.
        md_x_ln : cross md, ln;
    }
}

component dma_c {
    import cov_pkg::*;

    action xfer {
        rand bit[16]     len;
        rand xfer_mode_e mode;
        rand bit[4]      chan;

        constraint len in [1..4096];

        // Instantiating the reusable type, binding ports by name and setting
        // an instance option.
        xfer_cg cg(.len(len), .m(mode)) with {
            option.at_least = 2;
            option.comment  = "per-xfer value coverage";
        };

        // An in-line covergroup MAY reference the enclosing scope directly.
        covergroup {
            option.per_instance    = true;
            option.detect_overlap  = true;

            // An `iff` guard: sampled only when the condition holds.
            ch : coverpoint chan iff (mode == WIDE) {
                bins low  = [0..3];
                bins high = [4..15];
            }
        } inline_cg;
    }

    action read  { rand lock_mode_e lock_mode; }
    action write { rand xfer_mode_e write_mode; }
}

component pss_top {
    dma_c dma;
}

// extension_variants.pss
//
// Reuse mechanisms: inheritance, extension, overrides, templates, compile if.
//
// The governing distinction: INHERITANCE adds a choice someone must make;
// EXTENSION removes one -- it changes the type everywhere it is already used.
// Project configuration is almost always extension, packaged so that a tool
// can include or exclude it per test.
//
// Demonstrates:
//   - an abstract action as a shared base
//   - inheritance, and (in comments) super in a derived exec
//   - extension in its own package, and why a WILDCARD import is required
//   - type and instance overrides (in comments)
//   - a template type with a value parameter
//   - compile if driven by a package-scope constant
//
// See: reference/lang/structural/07-inheritance-extension-overrides.md
//      reference/lang/structural/01-packages-and-name-resolution.md

package config_pkg {
    // compile if conditions may reference only package-scope constants, and
    // only ones declared EARLIER in the processing order.
    static const bool HAS_FAST_PATH = true;
    static const int  MAX_LEN       = 4096;
}

package base_pkg {
    import config_pkg::*;

    // An abstract action may be declared outside a component. It captures the
    // shared fields and constraints and is never traversed directly.
    abstract action base_xfer {
        rand bit[16] len;
        constraint len > 0 && len <= MAX_LEN;
    }
}

component dma_c {
    import base_pkg::*;
    import config_pkg::*;
    import std_pkg::*;   // for message()

    // Inheritance: a NEW type that a traversal site must name explicitly.
    action xfer : base_xfer {
        exec body {
            message(LOW, "xfer len=%d", len);
        }
    }

    // A derived action's exec block REPLACES the base's. The `super;`
    // statement splices the base behaviour back in -- omitting it is a silent
    // loss of behaviour, and is the most damaging inheritance mistake in PSS.
    // `super;` is legal PSS (LRM 17.1, 20.1.4.2) but is not accepted by every
    // front end, so it is shown here rather than compiled:
    //
    //     action logged_xfer : xfer {
    //         exec body {
    //             super;                        // runs xfer's body first
    //             message(LOW, "logged");
    //         }
    //     }
    action logged_xfer : xfer {
        exec body {
            message(LOW, "logged");
        }
    }

    // compile if elaborates declarations conditionally. A disabled branch must
    // be syntactically valid but is NOT semantically checked -- which is why
    // package selection is usually the better tool.
    compile if (config_pkg::HAS_FAST_PATH) {
        action fast_xfer : xfer {
            constraint len >= 1024;
        }
    }

    action test {
        activity {
            do xfer;
            do logged_xfer;
        }
    }
}

// Configuration for one SoC, in its own package so that it can be included or
// excluded per test, and so that it may contradict soc_b_pkg freely.
package soc_a_pkg {
    import base_pkg::*;

    extend action dma_c::xfer {
        rand int in [1, 2, 4, 8] ta_width;      // a NEW attribute
        constraint ta_width < 4 -> len <= 256;  // and a layered constraint
    }
}

// A conflicting configuration. Both packages can exist in the source tree;
// a tool includes at most one in a given test.
package soc_b_pkg {
    extend action dma_c::xfer {
        constraint len <= 64;
    }
}

// A template type. Angle brackets are required at instantiation even when
// every parameter has a default.
package tmpl_pkg {
    struct base_payload_s {
        rand bit[8] core;
    }

    // A `compile assert (N > 0 && N <= 16, "N out of range");` here is the
    // idiomatic way to validate a template value parameter at elaboration
    // time (LRM 19.4); not every front end evaluates it correctly inside a
    // generic template, so it is described rather than compiled.
    struct wrapper_s <struct T : base_payload_s = base_payload_s, int N = 4> {
        rand T   payload;
        rand int in [1..N] count;
    }
}

component pss_top {
    // A WILDCARD import is required to see members introduced in an extension:
    // extensions are unnamed and cannot be imported explicitly.
    import soc_a_pkg::*;
    import tmpl_pkg::*;

    dma_c dma;

    wrapper_s<>               w_default;   // <> required
    wrapper_s<base_payload_s, 8> w_eight;

    action run {
        dma_c::xfer x;

        // ta_width is introduced by the extension in soc_a_pkg. It is
        // referenceable here ONLY because of the wildcard import above -- an
        // explicit import cannot bring in extensions, because extensions are
        // unnamed. Front ends differ in how completely they weave extension
        // members into a type, so the reference is described rather than
        // compiled:
        //
        //     constraint x.ta_width == 4;

        // Overrides substitute a subtype for a declared type.
        //   override { type dma_c::xfer with dma_c::logged_xfer; }  // all
        //   override { instance dma.x with dma_c::logged_xfer; }    // one
        // Resolution: highest in the containment tree wins; within a
        // container, instance beats type; later beats earlier. Overrides do
        // NOT apply to input/output/lock/share fields.

        activity {
            x;
        }
    }
}

// flow_basic.pss
//
// Flow objects, pools, implicit binding, and action inferencing.
//
// Demonstrates:
//   - buffer  : consumer starts after the producer COMPLETES
//   - stream  : producer and consumer start together (exactly one of each)
//   - state   : one object per pool, with `initial` and `prev`
//   - pool placement deciding per-instance vs shared exchange
//   - a partially specified activity completed by action inference
//
// See: reference/lang/structural/04-flow-objects.md
//      reference/lang/structural/06-pools-and-binding.md
//      reference/lang/activity/02-action-inferencing.md

package flow_basic_pkg {

    struct mem_segment_s {
        rand bit[32] addr;
        rand bit[16] size;
        constraint size in [4..4096];
        constraint addr % 4 == 0;
    }

    // Persistent data: the consumer runs after the producer completes.
    buffer data_buff_s {
        rand mem_segment_s seg;
    }

    // Transient data: producer and consumer run in parallel.
    // Exactly one producer and exactly one consumer.
    stream data_stream_s {
        rand mem_segment_s seg;
    }

    enum dma_mode_e { UNKNOWN, IDLE, ACTIVE }

    // A state variable: the pool holds exactly one of these at a time.
    state dma_state_s {
        rand dma_mode_e mode;

        // The object present before any action writes the pool.
        constraint initial -> mode == UNKNOWN;

        // A sequencing constraint relating this state to the previous one
        // would be written with the built-in `prev` reference. It is legal PSS
        // (LRM 9.3.3.1 g), but `prev` is not accepted by every front end, so it
        // is shown here rather than compiled -- note the `!initial` guard,
        // without which the constraint is unresolved for the initial object:
        //
        //     constraint !initial -> mode != prev.mode;
    }
}

component producer_c {
    import flow_basic_pkg::*;

    action produce {
        output data_buff_s out_data;
        rand bit[16]       len;
        constraint out_data.seg.size == len;
    }
}

component consumer_c {
    import flow_basic_pkg::*;

    action consume {
        input data_buff_s in_data;
        input dma_state_s st;
        constraint st.mode == ACTIVE;
    }
}

component dma_c {
    import flow_basic_pkg::*;

    // Pools live here, so each dma_c instance exchanges through its own.
    // Moving them to pss_top would make the two DMAs share.
    pool data_buff_s   buff_p;
    pool data_stream_s strm_p;
    pool dma_state_s   state_p;

    bind buff_p  *;
    bind strm_p  *;
    bind state_p *;

    producer_c prod;
    consumer_c cons;

    action set_mode {
        output dma_state_s st;
        rand dma_mode_e    to;
        constraint st.mode == to;
    }

    action stream_src { output data_stream_s s; }
    action stream_dst { input  data_stream_s s; }

    // Fully specified: every producer is traversed explicitly.
    action directed_test {
        set_mode           m;
        producer_c::produce p;
        consumer_c::consume c;

        activity {
            m;
            p;
            c;
        }

        constraint m.to == ACTIVE;
        constraint c.in_data.seg.size == p.out_data.seg.size;
    }

    // Partially specified: `consume` has two unbound inputs, so the tool
    // INFERS a `produce` and a `set_mode` and schedules them ahead of it.
    action inferred_test {
        activity {
            do consumer_c::consume;
        }
    }

    // A stream forces its producer and consumer to start together.
    action stream_test {
        activity {
            parallel {
                do stream_src;
                do stream_dst;
            }
        }
    }
}

component pss_top {
    dma_c dma0;
    dma_c dma1;
}

// procedural_realization.pss
//
// The realization half: exec blocks, functions, procedural statements, and the
// solve/target platform split.
//
// The governing rule: every piece of procedural code runs on the SOLVE platform
// (during generation) or the TARGET platform (in the generated test), and PSS
// enforces which functions each may call. Getting that wrong is the most common
// error in PSS.
//
// Demonstrates:
//   - init_down / init_up / pre_solve / post_solve / pre_body / body
//   - solve, target and unqualified functions, and where each may be called
//   - native parameter passing: scalars by value, aggregates by handle, const
//   - procedural statements: if, match, repeat, while, foreach, break/continue
//   - a target-template exec block with mustache references
//
// See: reference/lang/procedural/01-exec-blocks.md
//      reference/lang/procedural/02-functions.md
//      reference/lang/procedural/03-procedural-statements.md

package rt_pkg {
    import std_pkg::*;

    struct params_s {
        int x;
        int y;
    }

    // Unqualified: available on BOTH platforms. This is the default and the
    // right choice for pure computation.
    function int add(int a, int b) {
        return a + b;
    }

    // Solve platform only: callable from init_down/init_up/pre_solve/
    // post_solve/pre_body, and NEVER from body/run_start/run_end.
    solve function bit[32] alloc_addr(bit[32] size) {
        return 0x8000_0000 + size;
    }

    // Target platform only: callable from body/run_start/run_end, and NEVER
    // from a solve exec. Bound to a C function.
    import target C function void poke(bit[32] addr, bit[32] data);
    import target C function int  sample_dut();

    // Native functions take NO parameter direction modifiers -- input/output/
    // inout are for imported functions only. Scalars pass by value; aggregates
    // pass by HANDLE, so the callee mutates the caller's instance unless the
    // parameter is const.
    function void bump(params_s p, int a) {
        p.x = a;      // visible to the caller: p is a handle
        a = 0;        // NOT visible to the caller: a is a copy
    }

    function void copy_pair(const params_s src, params_s dst) {
        dst.x = src.x;
        dst.y = src.y;
        // src.x = 0;      // ERROR: src is const
    }

    // `pure` promises the result depends only on the parameters and that there
    // are no side effects -- the tool may CACHE it. Only non-void functions
    // with no output/inout parameters may be pure.
    pure function int square(int n) {
        return n * n;
    }

    // Every procedural statement, in one place.
    function int demo(array<int,8> a, int n) {
        int sum;                      // declare anywhere, reference after
        int i = 0;
        int j = 1;
        // rand int bad;              // ERROR: no rand in a procedural scope

        sum = 0;

        if (n > 0) {
            sum += n;                 // compound assignment: statements only
        } else {
            sum -= n;
        }

        repeat (4)       { sum += 1; }
        repeat (idx : 4) { sum += idx; }
        while (i < n)    { i += 1; }              // tested before
        repeat { j += 1; } while (j < n);         // tested after

        foreach (el : a) {
            if (el == 0)  break;                  // innermost loop
            if (el == 42) continue;
            sum += el;
        }

        // Exactly one arm must match. Without a default, an unmatched value is
        // a runtime error that nothing detects statically.
        match (n) {
            [0..3]:    sum = 1;
            [4..7]:    sum = 2;
            [8,16,32]: sum = 3;
            default:   sum = 4;
        }

        return sum;
    }
}

component dma_c {
    import rt_pkg::*;
    import std_pkg::*;

    bit[32] base_addr = 0x1000;

    // Component data is set during ELABORATION and read thereafter. An action
    // never writes comp.<field>.
    exec init_up {
        base_addr = 0x2000;
    }

    // An instance function, reached through `comp` from an action.
    function bit[32] ch_addr(int ch) {
        return base_addr + ch * 0x20;
    }

    action xfer {
        rand bit[32] size;
        rand int in [0..3] ch;

        bit[32] addr;                 // derived: NOT rand
        int     observed;             // filled in on the target platform

        constraint size in [4..4096];

        // Solve platform: initialize non-random fields the solve will read.
        exec pre_solve {
            addr = 0;
        }

        // Solve platform: compute non-rand fields from solved values.
        exec post_solve {
            addr = alloc_addr(size);        // solve function, solve exec: OK
            // poke(addr, size);            // ERROR: target function here
        }

        // A `exec pre_body { ... }` block runs on the solve platform AFTER
        // executor assignment and address allocation -- it is the only place
        // executor(), addr_value_solve() and addr_value_abs() may be called.
        // Not every front end implements it, so it is described rather than
        // compiled:
        //
        //     exec pre_body {
        //         print("xfer addr=0x%x size=%d\n", addr, size);
        //     }

        // Target platform: the action's actual implementation.
        exec body {
            int local;
            local = add(1, 2);              // unqualified: available here
            // addr = alloc_addr(size);     // ERROR: solve function here

            poke(comp.ch_addr(ch), addr);
            poke(addr, size);

            // Reading DUT state back is legal; it can steer a LATER activity
            // decision, but can never feed a constraint on this action.
            observed = sample_dut();

            // message() logs from the generated test. The verbosity, the
            // format string and any string arguments must be solve-time known,
            // and no argument may have a side effect (verbosity gating may
            // elide it entirely).
            message(LOW, "xfer %d bytes to 0x%x", size, addr);
        }
    }

    // A target-template exec emits TEXT rather than calling a function. Only
    // scalars may be referenced with {{...}}, and references are read-only.
    action emit_c {
        rand bit[2] func_id;
        rand bit[4] arg;

        exec header C = """
            #include "dut.h"
        """;

        exec body C = """
            func_{{func_id}}({{arg}});   {#} a mustache may sit inside an identifier
        """;
    }
}

component pss_top {
    dma_c dma;
}

// regs_and_mem.pss
//
// The register model and address spaces, end to end.
//
// Demonstrates:
//   - packed_s layout, and sizeof_s
//   - reg_c with a struct value type and with a bit-vector value type
//   - reg_group_c with exactly ONE offset scheme
//   - an MMIO window added as a NON-allocatable region
//   - allocatable memory, an address claim, and handle arithmetic
//   - register and memory access from a target exec
//
// See: reference/lang/platform/04-registers.md
//      reference/lang/platform/03-address-spaces.md

package dma_regs_pkg {
    import addr_reg_pkg::*;
    // packed_s and sizeof_s are std_pkg declarations (Annex C.1); import is
    // not re-export, so importing addr_reg_pkg alone does not bring them in.
    import std_pkg::*;

    // A packed struct describes the register's bit layout. The FIRST declared
    // field is at the lowest address. Only numeric types, bool, based enums,
    // packed structs and arrays of those are allowed.
    struct csr_s : packed_s<LITTLE_ENDIAN> {
        bit     en;
        bit[7]  rsvd;
        bit[8]  chan;
        bit[16] len;
    }

    // READWRITE and SZ = 8*sizeof_s<csr_s>::nbytes = 32 by default.
    pure component csr_r : reg_c<csr_s> {}

    // A bit-vector register: read()/read_val() are equivalent here.
    pure component sts_r : reg_c<bit[32], READONLY> {}

    // A register group supplies the offset of every element it contains,
    // using EITHER get_offset_of_instance + get_offset_of_instance_array,
    // OR get_offset_of_path. Implementing all three is an error.
    pure component ch_regs_c : reg_group_c {
        csr_r csr;
        sts_r sts;
        csr_r aux[4];

        function bit[64] get_offset_of_instance(string name) {
            match (name) {
                ["csr"]: return 0x0;
                ["sts"]: return 0x4;
                default: return -1;
            }
        }

        function bit[64] get_offset_of_instance_array(string name, int index) {
            match (name) {
                ["aux"]: return 0x10 + index * 4;
                default: return -1;
            }
        }
    }
}

component dma_c {
    import addr_reg_pkg::*;
    import dma_regs_pkg::*;

    // The top-level register group: the one that gets set_handle().
    ch_regs_c regs;

    // A transparent space lets a claim's absolute address be constrained
    // at solve time.
    transparent_addr_space_c<> sys_mem;

    exec init_up {
        // Allocatable memory.
        transparent_addr_region_s<> dram;
        addr_handle_t               dram_h;
        dram.size = 0x1000;
        dram.addr = 0x8000_0000;
        // A region may also carry a `tag` string, retrievable at run time with
        // get_tag(handle) -- `dram.tag = "dram";`
        dram_h = sys_mem.add_region(dram);

        // The MMIO window must be NON-allocatable, or the allocator will
        // hand out register addresses as buffers.
        transparent_addr_region_s<> mmio;
        addr_handle_t               mmio_h;
        mmio.size = 1024;
        mmio.addr = 0xA000_0000;
        mmio_h = sys_mem.add_nonallocatable_region(mmio);

        // Associated once, on the top-level group only, from an init exec.
        regs.set_handle(mmio_h);
    }

    // Register programming. All register access functions are `target`.
    action configure {
        rand bit[8]  chan;
        rand bit[16] len;

        constraint len > 0;

        exec body {
            // Whole-register write, by value.
            comp.regs.csr.write_val((len << 16) | (chan << 8));

            // Read-modify-write forms are the better way to say this, but are
            // not provided by every core-library implementation:
            //
            //   comp.regs.csr.write_fields({"chan","len"}, {chan, len});
            //   comp.regs.csr.write_masked({.en = ~0}, {.en = 1});
            //
            // write_field / write_fields take string LITERALS only, name
            // top-level non-aggregate fields only, and the names must be
            // unique. In write_masked, `~0` selects every bit of a field and
            // fields omitted from the literal default to 0, so they are
            // automatically excluded from the mask.
        }
    }

    // A READONLY register may be read but never written.
    action poll {
        exec body {
