package annotation_pkg {

    /// Declares an annotation type.
    annotation desc_c {
        string text;
        int priority;
    }

    annotation owner_c : desc_c {
        string team;
    }

    /// Applied bare, with no parameters, below.
    annotation deprecated { }

    @desc_c {.text = "a buffer of bytes", .priority = 3}
    buffer data_b {
        rand bit[7:0] payload[16];
    }

    component pss_top {

        @owner_c {.text = "top-level entry", .priority = 1, .team = "dv"}
        action entry_a {
            // Element annotation, no semicolon.
            @desc_c {.text = "the interesting field"}
            rand int size;

            // Bare application, no parameters.
            @deprecated
            rand bool legacy;

            activity {
                // Standalone annotation, with a semicolon.
                @desc_c {.text = "the write leg"};
                do write_a;
            }
        }

        action write_a { }
    }
}

/*
 * PSS 3.1 behavioral coverage: monitors, cover statements, and the activity
 * forms that only appear inside them (Clause 16, Syntax 73).
 *
 * The actions and monitors are declared inside `component pss_top` because
 * `package_body_item` (B.1) admits only `abstract_action_declaration` -- a bare
 * `action` at package scope is a syntax error.  See PROVENANCE.md, "Completing
 * LRM examples".
 */
package coverage_pkg {

    component pss_top {

        action write_a { rand int size; }
        action read_a  { rand int size; }
        action idle_a  { }

        monitor write_then_read_m {
            write_a w;
            read_a  r;

            constraint same_size { w.size == r.size; }

            activity {
                sequence {
                    w;
                    eventually r;
                }
            }
        }

        abstract monitor base_m {
            activity { }
        }

        monitor overlapping_m : base_m {
            write_a w;
            read_a  r;

            activity {
                overlap {
                    w;
                    r;
                }
            }
        }

        monitor concat_m {
            write_a a1, a2;
            activity {
                concat {
                    a1;
                    a2;
                }
            }
        }

        // Cover an existing monitor type.
        cover write_then_read_m;

        // Cover an inline scenario.
        interesting_c: cover {
            write_a w;
            read_a  r;
            activity {
                schedule {
                    w;
                    r;
                }
            }
        }

        covergroup size_cg (int s) {
            option.per_instance = true;
            cp_size: coverpoint s {
                bins small[]  = [0..7];
                bins large    = [8..31];
                ignore_bins  zero = [0];
                illegal_bins neg  = [-1];
            }
            cp_cross: cross cp_size, cp_size;
        }
    }
}

/*
 * Triple-quoted target templates with mustache expressions and control-flow
 * directives (Clause 4.7.1, Mantis8730/8356), plus the 3.1 activity forms
 * `replicate`, `symbol` and `yield`.
 *
 * The actions are declared inside `component gen_c` because `package_body_item`
 * (B.1) admits only `abstract_action_declaration` -- a bare `action` at package
 * scope is a syntax error.  See PROVENANCE.md, "Completing LRM examples".
 */
package template_pkg {

    function void pause() {
        yield;
    }

    component gen_c {

        string name;

        action gen_a {
            rand int count;
            rand bit[31:0] base_addr;
            string name;

            symbol setup_s {
                do init_a;
                do config_a;
            }

            activity {
                setup_s;
                replicate (i: count) {
                    do write_a with { index == i; };
                }
                replicate (count) leg[]: parallel {
                    do read_a;
                }
            }

            exec body C = """
                /* {{name}}: emitted {{count}} times */
                {% foreach (i : count) %}
                write32({{base_addr}} + {{i}} * 4, {{i}});
                {%%}
                {% if (count > 0) %}
                printf("wrote %d words\n", {{count}});
                {%%}
            """;

            exec header SV = """
                import uvm_pkg::*;
            """;
        }

        action init_a { }
        action config_a { }
        action write_a { rand int index; }
        action read_a { }

        // Target-file exec: the operand is a filename, not a language.  B.7
        // cannot derive this (it gives component_body_item ::= ... | exec_block),
        // but Example 309 uses exactly this form -- see the note on
        // component_body_item in PSSParser.g4.
        exec file "out/manifest.txt" = """
            generated by {{name}}
        """;
    }
}

